import {createHash} from 'node:crypto';
import {atomicJson,fileSha,digest,validateArtifactDigest} from './backend/research/browser_runtime/xc1_artifacts.mjs';
const phase='PHASE_9G_XC2_R2_DIRECT_CONFLICT_RESERVATION',root='backend/data/work/xc2_r2_direct_conflict';
const dir='backend/research/reports',start='c0f3b504ede2e9bb9a77c51bf4a69436bcb8e474';
const load=async p=>JSON.parse(await readFile(p,'utf8')),sha=b=>createHash('sha256').update(b).digest('hex');
const reports=[];
for(const name of(await readdir(dir)).filter(n=>n.startsWith('phase9g_xc2_r1_')).sort()){
 const path=dir+'/'+name,bytes=await readFile(path),blob=execFileSync('git',['show',start+':'+path],{maxBuffer:50e6});
 reports.push({path,fileSha256:sha(bytes),gitBlobSha256:sha(blob),gitBlobOid:execFileSync('git',['rev-parse',start+':'+path],{encoding:'utf8'}).trim(),fileEqualsGitBlob:bytes.equals(blob),bytes:bytes.length});
}
if(reports.some(r=>!r.fileEqualsGitBlob))throw Error('HISTORICAL_WORKTREE_DIFF');
const finalPath=dir+'/phase9g_xc2_r1_bounded_runtime_final_2026-10-16.json',current=await load(finalPath),prior=structuredClone(current);
const removedFields=['implementationScopeClarification','scopeAndExecutionProof','evidenceInterpretation','knownEvidenceLimitations'];
for(const k of removedFields)delete prior[k];
prior.additionalEvidence=prior.additionalEvidence.filter(p=>!p.includes('post_run_asset_verification'));
const priorBytes=Buffer.from(JSON.stringify(prior,null,2)+'\n'),priorSha=sha(priorBytes);
if(priorSha!=='894813fbd9c014b53d24c24ed116ad5ae1238bf71b8c5553b6cae8a0a94637f0')throw Error('PRIOR_RECONSTRUCTION_FAILED');
const intermediate=structuredClone(prior);
for(const k of removedFields)intermediate[k]=current[k];
const rebuilt=structuredClone(intermediate);rebuilt.additionalEvidence.push(current.additionalEvidence.at(-1));
if(sha(Buffer.from(JSON.stringify(rebuilt,null,2)+'\n'))!=='fa03b6429c542d6be9c79efce4501907bc936979c69f6e9cdcbb5d791510103e')throw Error('FINAL_RECONSTRUCTION_FAILED');
const differences=[];
function diff(a,b,path='$'){
 if(JSON.stringify(a)===JSON.stringify(b))return;
 if(a&&b&&typeof a==='object'&&typeof b==='object'&&!Array.isArray(a)&&!Array.isArray(b)){
  for(const k of new Set([...Object.keys(a),...Object.keys(b)])){if(!(k in a))differences.push({path:path+'.'+k,operation:'ADD',value:b[k]});else if(!(k in b))differences.push({path:path+'.'+k,operation:'REMOVE',value:a[k]});else diff(a[k],b[k],path+'.'+k);}
 }else if(Array.isArray(a)&&Array.isArray(b)&&b.length===a.length+1&&JSON.stringify(a)===JSON.stringify(b.slice(0,-1)))differences.push({path:path+'['+a.length+']',operation:'ADD',value:b.at(-1)});
 else differences.push({path,operation:'REPLACE',before:a,after:b});
}
diff(prior,current);
const expectedPaths=new Set(removedFields.map(k=>'$.'+k).concat('$.additionalEvidence[8]'));
if(differences.some(d=>!expectedPaths.has(d.path))||differences.length!==5)throw Error('SCIENTIFIC_REPORT_DIFF');
const freeze=await load(dir+'/phase9g_xc2_r1_policy_freeze_2026-10-16.json'),checks=[];
async function check(path,expected,kind){const actual=await fileSha(path);if(actual!==expected)throw Error(kind+':'+path);checks.push({path,sha256:actual,kind});}
for(const s of freeze.sources)await check(s.path,s.sha256,'FROZEN_SOURCE');
for(const s of freeze.historicalFiles)await check(s.path,s.sha256,'ORIGINAL_XC2_REPORT');
const manifest=await load(dir+'/phase9g_xc2_r1_evidence_manifest_2026-10-16.json');
for(const s of manifest.files)await check(s.path,s.sha256,'R1_EVIDENCE_MANIFEST');
const raw=await load(dir+'/phase9g_xc2_causal_execution_receipts_2026-10-16.json');
for(const r of raw.receipts){const p=r.path.replaceAll('\\','/');await check(p,r.fileSha256,'SEALED_ORIGINAL_ACOUSTIC_ARTIFACT');validateArtifactDigest(await load(p));}
for(const r of current.originalVsBoundedCorrectnessAndLatency.rows)await check(r.path,r.sha256,'R1_REPLAY');
const witnesses=await load(dir+'/phase9g_xc2_r1_bounded_witness_manifest_2026-10-16.json');
for(const r of witnesses.rows)await check(r.path,r.sha256,'R1_WITNESSES');
const runtime=await load(dir+'/phase9g_xc2_r1_causal_runtime_receipts_2026-10-16.json');
for(const r of runtime.rows){await check(r.path,r.sha256,'R1_RUNTIME');validateArtifactDigest(await load(r.path));}
const assets=await load(dir+'/phase9g_xc2_r1_post_run_asset_verification_2026-10-16.json');
for(const r of assets.rows)await check(r.path,r.actual,'FIR_OR_SCIENTIFIC_PCM_FIXTURE');
await check('backend/data/work/xc2_r1_bounded_runtime/preparation.json',freeze.preparationSha256,'R1_PREPARATION');
await mkdir(root,{recursive:true});await writeFile(root+'/reconstructed_894813_report.json',priorBytes,{flag:'wx'});
const generator=await load(dir+'/phase9g_xc2_r1_evidence_generation_receipt_2026-10-16.json');
const result={phase,startingRemoteHead:start,status:'R1_EVIDENCE_PROVENANCE_RECONCILED_NO_SCIENTIFIC_CHANGE',
 relevantR1GitBlobAndFileIdentities:reports,recordedIntermediateSha256:priorSha,committedFinalSha256:await fileSha(finalPath),
 priorBytesReconstructed:true,reconstructedBytes:priorBytes.length,reconstructedPath:root+'/reconstructed_894813_report.json',
 originalIntermediateProducer:{receipt:dir+'/phase9g_xc2_r1_evidence_generation_receipt_2026-10-16.json',sourceSha256:sha(Buffer.from(generator.generatorSource)),invocation:'node --max-old-space-size=8192 --input-type=module -e <generatorSource>',operation:'Writes draft plus postGenerationInterpretation, bounded safety-tradeoff label, eight additionalEvidence links and pre-evidence GitHub receipt; JSON.stringify(...,null,2)+LF. Receipt SHA is this intermediate state, not the final report.'},
 subsequentOperations:[{operation:'Append scope clarification, scope-proof link, interpretation link and12knownEvidenceLimitations; serialize pretty JSON+LF',intermediateSha256:sha(Buffer.from(JSON.stringify(intermediate,null,2)+'\n')),addedPaths:removedFields},
 {operation:'Append post_run_asset_verification receipt at additionalEvidence[8]; serialize pretty JSON+LF; recompute evidence manifest',resultSha256:await fileSha(finalPath)}],
 sourceAvailability:'The intermediate producer is versioned verbatim in generatorSource. Subsequent read-only report packaging commands are in the prior conversation tool history, not separate retained executable files. Their exact data operations are losslessly reconstructed here; both endpoint byte hashes match. No claim that an unretained intermediate file was independently archived.',
 semanticJsonDiff:differences,
 scientificContentIdentical: {policy:digest(prior.boundedPolicy)===digest(current.boundedPolicy),mathematicalHorizon:digest(prior.mathematicalHorizon)===digest(current.mathematicalHorizon),replayMetrics:digest(prior.originalVsBoundedCorrectnessAndLatency)===digest(current.originalVsBoundedCorrectnessAndLatency),runtimeReceipts:digest(prior.runtimeDeconfounding)===digest(current.runtimeDeconfounding),firParity:digest(prior.browserBandLimited)===digest(current.browserBandLimited),conclusions:digest(prior.conclusions)===digest(current.conclusions)},
 verificationChecks:checks,verificationCount:checks.length,checksDigest:digest(checks),
 interpretation:'Provenance receipt captured an intermediate report hash, while manifest captured the later final packaging state. This is a reporting-chain omission, not a scientific-policy or measurement change.',
 historicalReportsEdited:false,newNeuralInferenceCount:0,generatorSource:process._eval};
await atomicJson(dir+'/phase9g_xc2_r2_r1_hash_reconciliation_2026-10-16.json',result);
console.log(JSON.stringify({status:result.status,checks:checks.length,diffPaths:differences.map(d=>d.path)}));
